"use client";

import Image from "next/image";
import { useEffect, useState } from "react";
import profile1 from "~/assets/profile/profile-1.jpg";
import profile2 from "~/assets/profile/profile-2.jpeg";

const FOUNDER_IMAGES = [profile1, profile2];

export default function CreatorImage() {
  const [currentImage, setCurrentImage] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentImage((prev) => (prev + 1) % FOUNDER_IMAGES.length);
    }, 3000);

    return () => clearInterval(interval);
  }, []);

  return (
    <div className="hp-creator-image-wrapper">
      {FOUNDER_IMAGES.map((img, index) => (
        <Image
          key={img.src}
          src={img}
          alt="Sathish Kumar, founder of Pinktra"
          fill
          placeholder="blur"
          sizes="(max-width: 768px) 320px, 420px"
          priority={index === 0}
          className={`hp-creator-img-slide ${index === currentImage ? "active" : ""}`}
        />
      ))}
    </div>
  );
}
